export function getCourseById(id) {
    return COURSE_CATALOG.find((c) => c.id === id);
}
export function getCourseByName(name) {
    if (!name)
        return undefined;
    const lower = name.toLowerCase().trim();
    return COURSE_CATALOG.find((c) => c.name.toLowerCase() === lower ||
        c.id.toLowerCase() === lower ||
        c.name.toLowerCase().includes(lower) ||
        lower.includes(c.name.toLowerCase()));
}
export function getCourseSyllabusInfo(courseNameOrId) {
    const course = getCourseByName(courseNameOrId) || getCourseById(courseNameOrId);
    if (course) {
        return {
            examBody: course.examBody,
            syllabusVersion: course.syllabusVersion,
            isVerified: course.isVerified,
        };
    }
    return {
        examBody: "Custom / Unverified",
        syllabusVersion: "User Defined",
        isVerified: false,
    };
}
export function findSubjectInCatalog(courseNameOrId, subjectNameOrCode) {
    const course = getCourseByName(courseNameOrId) || getCourseById(courseNameOrId);
    if (!course)
        return undefined;
    const sLower = subjectNameOrCode.toLowerCase().trim();
    return course.subjects.find((s) => s.name.toLowerCase() === sLower ||
        s.code.toLowerCase() === sLower ||
        s.name.toLowerCase().includes(sLower));
}
